//! Implementation for the Abacus procedural macro.
//!
//! This is responsible for parsing DSL inputs and auto-generating the type-stated
//! tock-registers (as Abacus is a wrapper around tock-registers). The autogenerated
//! code assumes the user of this proc-macro has tock-registers 0.10.0 as a dependency.
//!
//! Usage:
//! The proc macro consists of two parts to annotate a peripheral register block:
//! 1) `process_register_block` macro to annotate the peripheral register block struct.
//! 2) `RegAttributes` macro to define the peripheral states, registers, and transitions.
//!
//! #[repr(C)]
//! #[process_register_block(
//!     peripheral_name = "Nrf5xTemp",
//!     register_base_addr = 0x4000C000,
//!     states = [              <------------ Define peripheral states
//!         (Off, cost: 1),
//!         (Reading, cost: 5),
//!     ]
//! )]
//!
//!

mod cost;
mod generating;
mod macro_input;
mod parsing;
mod register;

use proc_macro::TokenStream;
use quote::{format_ident, quote};
use syn::{DeriveInput, Field, Type};

use std::collections::HashSet;

use crate::generating::generate_state_enum;
use crate::macro_input::{Backend, MacroInput};
use crate::register::Register;

#[proc_macro_attribute]
pub fn process_register_block(attr: TokenStream, item: TokenStream) -> TokenStream {
    expand_register_block(attr.into(), item.into())
        .unwrap_or_else(syn::Error::into_compile_error)
        .into()
}

fn expand_register_block(
    attr: proc_macro2::TokenStream,
    item: proc_macro2::TokenStream,
) -> syn::Result<proc_macro2::TokenStream> {
    let metadata = cost::metadata(attr.clone(), item.clone());
    let parsed_input: MacroInput = syn::parse2(attr.clone())?;
    let register = format_ident!("{}Registers", parsed_input.peripheral_name);
    let internal_register = format_ident!("Block");
    let state_enum_ident = format_ident!("{}StateEnum", parsed_input.peripheral_name);
    let inferred_state_ident = format_ident!("{}InferredState", parsed_input.peripheral_name);

    if let Backend::External(backend) = &parsed_input.backend {
        return expand_external_register_block(
            attr,
            item,
            &parsed_input,
            backend,
            &register,
            &state_enum_ident,
            &inferred_state_ident,
        );
    }

    let mut result = add_imports();
    result.extend(generate_register_wrapper(
        &register,
        &internal_register,
        &inferred_state_ident,
    ));
    result.extend(generate_state_enum(
        &parsed_input.state_definitions,
        &register,
        &state_enum_ident,
    ));

    let (states_generated, _) = parsed_input.generate_states(&register, &state_enum_ident)?;
    result.extend(states_generated);

    let ast: DeriveInput = syn::parse2(item)?;
    let data = match &ast.data {
        syn::Data::Struct(data) => data,
        _ => {
            return Err(syn::Error::new_spanned(
                &ast,
                "expected a register block struct",
            ))
        }
    };

    let (field_details, reg_vec) = process_struct_fields(&data.fields)?;
    result.extend(generate_register_bindings(
        &reg_vec,
        &register,
        &inferred_state_ident,
    )?);
    result.extend(register_type_definitions());
    result.extend(quote! {
        #[repr(C)]
        pub struct #internal_register<S: State> {
            #(#field_details),*
        }
    });

    result.extend(metadata);
    Ok(result)
}

fn expand_external_register_block(
    attr: proc_macro2::TokenStream,
    item: proc_macro2::TokenStream,
    input: &MacroInput,
    backend: &syn::Path,
    register: &syn::Ident,
    state_enum: &syn::Ident,
    inferred_state: &syn::Ident,
) -> syn::Result<proc_macro2::TokenStream> {
    let ast: DeriveInput = syn::parse2(item.clone())?;
    let syn::Data::Struct(data) = &ast.data else {
        return Err(syn::Error::new_spanned(ast, "expected a model struct"));
    };
    if !data.fields.is_empty() {
        return Err(syn::Error::new_spanned(
            data.fields.clone(),
            "an external-backend model must be a unit struct",
        ));
    }

    let declared = |state: &parsing::State| {
        input
            .state_definitions
            .iter()
            .any(|definition| definition.state == *state)
    };
    let mut seen = HashSet::new();
    let mut transition_impls = proc_macro2::TokenStream::new();
    for transition in &input.transitions {
        if !declared(&transition.from) || !declared(&transition.to) {
            return Err(syn::Error::new_spanned(
                transition.to.form_state_marker_type(),
                "external transition states must be declared in states",
            ));
        }
        let from = transition.from.form_state_marker_type();
        let to = transition.to.form_state_marker_type();
        let target = input
            .state_definitions
            .iter()
            .find(|definition| definition.state == transition.to)
            .expect("declared transition target");
        let method = format_ident!("into_{}", target.state_shortname.to_string().to_lowercase());
        if !seen.insert((from.to_string(), method.to_string())) {
            return Err(syn::Error::new_spanned(
                &transition.to.state_name,
                "duplicate external transition method",
            ));
        }
        transition_impls.extend(quote! {
            impl #register<#from> {
                pub(crate) fn #method(self) -> #register<#to> {
                    #register {
                        peripheral: self.peripheral,
                        state: PhantomData,
                    }
                }
            }
        });
    }

    let metadata = cost::metadata(attr, item);
    let mut result = quote! {
        use abacus_registers::{Reg, State, StateEnum, SubState, SyncState, TransientStateReg};
        use core::convert::TryFrom;
        use core::marker::PhantomData;

        #[allow(missing_docs)]
        pub struct #inferred_state;
        impl State for #inferred_state {}

        #[allow(missing_docs)]
        pub struct #register<S: State = #inferred_state> {
            peripheral: #backend,
            state: PhantomData<S>,
        }

        impl<S: State> #register<S> {
            /// Wrap an externally owned PAC handle in an asserted initial state.
            ///
            /// # Safety
            /// The caller must exclusively own the peripheral and ensure that its
            /// hardware state is `S`.
            pub const unsafe fn new(peripheral: #backend) -> Self {
                Self { peripheral, state: PhantomData }
            }

            pub(crate) fn peripheral(&self) -> &#backend {
                &self.peripheral
            }
        }

        #transition_impls
    };
    result.extend(generate_state_enum(
        &input.state_definitions,
        register,
        state_enum,
    ));
    let (states, _) = input.generate_states(register, state_enum)?;
    result.extend(states);
    result.extend(metadata);
    Ok(result)
}

fn add_imports() -> proc_macro2::TokenStream {
    quote!(
        use abacus_registers::{
            State, SubState, StateEnum, Reg, SyncState, TransientStateReg, AbacusStaticRef,
        };
        use core::marker::PhantomData;
        use core::mem::transmute;
        use core::ops::Deref;
        use abacus_registers::tock_registers::{
            fields::FieldValue, UIntLike, RegisterLongName, fields::Field, LocalRegisterCopy,
            interfaces::ReadWriteable,
        };
        use core::convert::TryFrom;
    )
}

fn generate_register_wrapper(
    register: &syn::Ident,
    internal_register: &syn::Ident,
    inferred_state: &syn::Ident,
) -> proc_macro2::TokenStream {
    quote! {
        pub struct #inferred_state;
        impl State for #inferred_state {}

        pub struct #register<S: State = #inferred_state> {
            reg:  AbacusStaticRef<#internal_register<S>>,
        }

        impl <S: State> #register<S> {
            pub const unsafe fn new(base_addr: usize) -> #register<S> {
                let reg = unsafe { AbacusStaticRef::new(base_addr as *const #internal_register<S>) };
                #register { reg }
            }
        }

        impl <S: State> Deref for #register<S> {
            type Target = #internal_register<S>;
            fn deref(&self) -> &#internal_register<S> {
                self.reg.deref()
            }
        }
    }
}

fn process_struct_fields(
    fields: &syn::Fields,
) -> syn::Result<(Vec<proc_macro2::TokenStream>, Vec<Register>)> {
    let mut reg_vec = Vec::new();
    let field_details: Vec<_> = fields
        .iter()
        .map(|field| {
            let (tokens, mut registers) = process_field(field)?;
            reg_vec.append(&mut registers);
            Ok(tokens)
        })
        .collect::<syn::Result<Vec<_>>>()?;
    Ok((field_details, reg_vec))
}

fn process_field(field: &Field) -> syn::Result<(proc_macro2::TokenStream, Vec<Register>)> {
    let field_type = field.ty.clone();
    let field_name = field
        .ident
        .clone()
        .ok_or_else(|| syn::Error::new_spanned(field, "expected a named register field"))?;

    let requires_gen = field
        .attrs
        .iter()
        .any(|attr| attr.path().is_ident("RegAttributes"));

    let field_attr: Vec<_> = field
        .attrs
        .iter()
        .filter_map(|attr| {
            if !attr.path().is_ident("RegAttributes") {
                Some(quote! {#attr})
            } else {
                None
            }
        })
        .collect();

    if !requires_gen {
        return Ok((
            quote! { #(#field_attr)* pub #field_name: #field_type },
            vec![],
        ));
    }

    let reg_attr_vec = field
        .attrs
        .iter()
        .filter_map(|attr| {
            if attr.path().is_ident("RegAttributes") {
                Some(attr.parse_args::<parsing::RegisterAttributes>())
            } else {
                None
            }
        })
        .collect::<syn::Result<Vec<_>>>()?;

    let Type::Path(type_path) = &field_type else {
        return Err(syn::Error::new_spanned(
            &field_type,
            "expected a tock-registers type",
        ));
    };
    let segment =
        type_path.path.segments.last().ok_or_else(|| {
            syn::Error::new_spanned(&field_type, "expected a tock-registers type")
        })?;
    let syn::PathArguments::AngleBracketed(args) = &segment.arguments else {
        return Err(syn::Error::new_spanned(
            segment,
            "expected two register type arguments",
        ));
    };
    if args.args.len() != 2 {
        return Err(syn::Error::new_spanned(
            args,
            "expected two register type arguments",
        ));
    }
    let register_bitwidth = match &args.args[0] {
        syn::GenericArgument::Type(Type::Path(path)) => path.path.get_ident().cloned(),
        _ => None,
    }
    .ok_or_else(|| {
        syn::Error::new_spanned(&args.args[0], "expected a register bitwidth identifier")
    })?;
    let register_shortname = args.args[1].clone();
    if !matches!(register_shortname, syn::GenericArgument::Type(_)) {
        return Err(syn::Error::new_spanned(
            &register_shortname,
            "expected a register marker type",
        ));
    }

    let mut output = proc_macro2::TokenStream::new();
    let mut registers = Vec::new();
    let mut first_item = true;

    for reg_attr in reg_attr_vec {
        registers.push(Register {
            name: field_name.clone(),
            valid_states: reg_attr.valid_states,
            register_shortname: register_shortname.clone(),
            register_type: reg_attr.register_type.clone(),
            register_bitwidth: register_bitwidth.clone(),
        });

        let reg_type = format_ident!("{}Register", &reg_attr.register_type.to_ident());
        if first_item {
            output.extend(quote! {
                #(#field_attr)*
                pub #field_name: #reg_type<#register_bitwidth, #register_shortname, S>
            });
            first_item = false;
        }
    }

    let output = if output.is_empty() {
        quote! { #(#field_attr)* pub #field_name: #field_type }
    } else {
        output
    };

    Ok((output, registers))
}

fn generate_register_bindings(
    reg_vec: &[Register],
    register: &syn::Ident,
    inferred_state: &syn::Ident,
) -> syn::Result<proc_macro2::TokenStream> {
    let mut result = proc_macro2::TokenStream::new();
    let mut seen = HashSet::new();
    for reg in reg_vec {
        let binding = reg.generate_register_op_bindings(register)?;
        if seen.insert(binding.clone().to_string()) {
            result.extend(binding);
        }
        let inferred = reg.generate_inferred_bindings(register, inferred_state);
        if seen.insert(inferred.clone().to_string()) {
            result.extend(inferred);
        }
    }
    Ok(result)
}

fn register_type_definitions() -> proc_macro2::TokenStream {
    quote! {
        pub enum RegisterResult<A: Reg, B: Reg> {
            Ok(A),
            Err(B),
        }

        impl <A: Reg, B: Reg> From<Result<A, B>> for RegisterResult<A, B> {
            fn from(result: Result<A, B>) -> Self {
                match result {
                    Ok(val) => RegisterResult::Ok(val),
                    Err(err) => RegisterResult::Err(err),
                }
            }
        }

        impl <A: Reg, B: Reg> RegisterResult<A, B> {
            fn into_closure_return<C, D>(self) -> Result<C, D>
            where
                C: StateEnum + From<A>,
                D: StateEnum + From<B>,
            {
                match self {
                    RegisterResult::Ok(val) => Ok(val.into()),
                    RegisterResult::Err(reg) => Err(reg.into())
                }
            }
        }

        pub struct StateChangeRegister<T: UIntLike, R: RegisterLongName, S: State> {
            pub(crate) reg: ReadWrite<T, R>,
            associated_state: PhantomData<S>,
        }

        pub struct ReadWriteRegister<T: UIntLike, R: RegisterLongName, S: State> {
            reg: ReadWrite<T, R>,
            associated_state: PhantomData<S>,
        }

        pub struct ReadOnlyRegister<T: UIntLike, R: RegisterLongName, S: State> {
            reg: ReadOnly<T, R>,
            associated_state: PhantomData<S>,
        }

        pub struct WriteOnlyRegister<T: UIntLike, R: RegisterLongName, S: State> {
            reg: WriteOnly<T, R>,
            associated_state: PhantomData<S>,
        }
    }
}

#[doc = include_str!("../COST_CHECKING.md")]
#[proc_macro_attribute]
pub fn heliod(attr: TokenStream, item: TokenStream) -> TokenStream {
    cost::start(attr.into(), item.into())
        .unwrap_or_else(syn::Error::into_compile_error)
        .into()
}

/// Declares the state effect and cost of an opaque peripheral operation.
///
/// The surrounding `#[heliod(...)]` analysis consumes this contract while the
/// Rust compiler receives the function unchanged. This is useful at abstraction
/// boundaries such as a userspace syscall wrapper, where the checked peripheral
/// implementation is not in the same crate as the caller.
#[proc_macro_attribute]
pub fn heliod_operation(_attr: TokenStream, item: TokenStream) -> TokenStream {
    item
}

#[doc(hidden)]
#[proc_macro]
pub fn __heliod(input: TokenStream) -> TokenStream {
    cost::expand(input.into())
        .unwrap_or_else(syn::Error::into_compile_error)
        .into()
}

#[cfg(test)]
mod tests {
    use super::expand_register_block;
    use quote::quote;

    #[test]
    fn malformed_register_blocks_return_diagnostics() {
        let attributes = quote! {
            peripheral_name = "Test", register_base_addr = 0,
            states = [(Off, cost: 0)]
        };
        let cases = [
            (
                quote! { enum Registers { Off } },
                "expected a register block struct",
            ),
            (
                quote! { struct Registers(u32); },
                "expected a named register field",
            ),
            (
                quote! { struct Registers { #[RegAttributes([Off], ReadOnly)] data: [u32; 2] } },
                "expected a tock-registers type",
            ),
            (
                quote! { struct Registers { #[RegAttributes([Off], ReadOnly)] data: ReadOnly } },
                "expected two register type arguments",
            ),
            (
                quote! { struct Registers { #[RegAttributes([Off], ReadOnly)] data: ReadOnly<u32> } },
                "expected two register type arguments",
            ),
            (
                quote! { struct Registers { #[RegAttributes([Off], ReadOnly)] data: ReadOnly<3, Marker> } },
                "expected a register bitwidth identifier",
            ),
            (
                quote! { struct Registers { #[RegAttributes([Off], ReadOnly)] data: ReadOnly<u32, 3> } },
                "expected a register marker type",
            ),
            (
                quote! { struct Registers { #[RegAttributes([], ReadOnly)] data: ReadOnly<u32, Marker> } },
                "expected at least one valid register state",
            ),
        ];
        for (item, message) in cases {
            let error = expand_register_block(attributes.clone(), item).unwrap_err();
            assert!(error.to_string().contains(message), "{error}");
            assert!(error
                .into_compile_error()
                .to_string()
                .contains("compile_error"));
        }
    }

    #[test]
    fn invalid_peripheral_names_and_unsupported_substates_return_diagnostics() {
        for (attributes, message) in [
            (
                quote! { peripheral_name = "not a name", register_base_addr = 0, states = [(Off, cost: 0)] },
                "peripheral_name must be a Rust identifier",
            ),
            (
                quote! { peripheral_name = "Test", register_base_addr = 0, states = [(Active(A, B, C), ActiveABC, cost: 0)] },
                "Only 2 substates are supported",
            ),
        ] {
            let error =
                expand_register_block(attributes, quote! { struct Registers { reserved: u32 } })
                    .unwrap_err();
            assert!(error.to_string().contains(message), "{error}");
        }
    }

    #[test]
    fn external_backend_wraps_the_pac_without_generating_an_mmio_block() {
        let expanded = expand_register_block(
            quote! {
                peripheral_name = "Temp",
                backend = external(pac::temp::Temp),
                states = [(Off, cost: 0), (Reading, *T*, cost: 1)],
                transitions = [Off => Reading, Reading => Off]
            },
            quote! { struct TempModel; },
        )
        .unwrap()
        .to_string();

        assert!(expanded.contains("peripheral : pac :: temp :: Temp"));
        assert!(expanded.contains("fn into_reading"));
        assert!(expanded.contains("fn into_off"));
        assert!(!expanded.contains("AbacusStaticRef"));
        assert!(!expanded.contains("struct Block"));
    }

    #[test]
    fn external_backend_rejects_fields_and_unknown_transition_states() {
        let attributes = quote! {
            peripheral_name = "Temp",
            backend = external(pac::temp::Temp),
            states = [(Off, cost: 0)],
            transitions = [Off => Reading]
        };
        let error = expand_register_block(attributes, quote! { struct TempModel; }).unwrap_err();
        assert!(error
            .to_string()
            .contains("external transition states must be declared"));

        let error = expand_register_block(
            quote! {
                peripheral_name = "Temp",
                backend = external(pac::temp::Temp),
                states = [(Off, cost: 0)]
            },
            quote! { struct TempModel { value: u32 } },
        )
        .unwrap_err();
        assert!(error
            .to_string()
            .contains("external-backend model must be a unit struct"));
    }
}
